using System;using System.Collections.Generic;using System.Linq;using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests {
internal static class NativeBootstrapProtocolTests {
 private const string Id="11111111-1111-4111-8111-111111111111",NewId="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",NewArea="fedcba9876543210fedcba9876543210";
 private static int Main(){var tests=new TestRunner();
 tests.Run("closed main bootstrap complete request",()=>TestRunner.Equal(0,Request().Validate().Count,"Valid native bootstrap request refused."));
 foreach(var name in new[]{"missing selection","foreign scenario","foreign case","not base only","saved load","second write","wrong leaf","schema1","persistence input","persistence case","route"})tests.Run("bootstrap rejects "+name,()=>{var r=Request();switch(name){case "missing selection":r.NativeBootstrap=null;break;case "foreign scenario":r.Scenario="fixture-intake";break;case "foreign case":r.NativeBootstrap.Case="any-main";break;case "not base only":r.NativeBootstrap.BaseGameOnly=false;break;case "saved load":r.NativeBootstrap.ExpectedNativeLoadCount=1;break;case "second write":r.NativeBootstrap.ExpectedNativeWriteCount=2;break;case "wrong leaf":r.NativeBootstrap.NativeWriteLeaf="Auto_2.zks";break;case "schema1":r.SchemaVersion=1;break;case "persistence input":r.PersistenceLoad=r.Fixture.Working;break;case "persistence case":r.PersistenceCase="multi-exploration-manual";break;case "route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;}TestRunner.True(r.Validate().Count>0,"Foreign native authority admitted.");});
 tests.Run("bootstrap exact rows and no wildcard",()=>{foreach(var row in new[]{"C7-bootstrap-preflight","C7-bootstrap-native-start","C7-bootstrap-native-world","C7-bootstrap-autosave","C7-bootstrap-cleanup","C7-bootstrap-runtime","C7-bootstrap-interrupted"})TestRunner.True(RuntimeSubscenarioResult.IsMissionScenario(row),"Missing selected row.");TestRunner.True(!RuntimeSubscenarioResult.IsMissionScenario("C7-bootstrap-any"),"Wildcard admitted.");});
 tests.Run("historical Working intake remains valid without bootstrap",()=>{var r=Request();r.NativeBootstrap=null;r.Scenario="fixture-intake";TestRunner.Equal(0,r.Validate().Count,"Historical intake was narrowed.");});
 tests.Run("zero load cap blocks eligibility before world disposal and native admission",()=>{var f=new Fixture();var a=f.Scope();TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Pre-disposal load eligibility admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Actual native load admitted.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"A refused load spent authority.");});
 tests.Run("read-only enumeration checks identity without granting loads",()=>{var f=new Fixture();var a=f.Scope();TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Exact native metadata refused.");TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Metadata check granted load.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Metadata spent load.");});
 tests.Run("native bootstrap window mints once and caps first write",()=>{var f=new Fixture();var a=f.Scope();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)!=null,"Closed window wrote.");a.OpenBootstrapWindow();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)==null,"First native write refused.");TestRunner.Equal(NewId,a.BootstrapGameId,"Native identity differs.");TestRunner.Equal(1,a.BootstrapFreezeCount,"Wrong freeze count.");TestRunner.True(!a.BootstrapWindowOpen,"Window did not close.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)!=null,"Second native write admitted.");TestRunner.Equal(1,a.AdmittedNativeWriteRequests,"Write cap changed.");});
 tests.Run("unused bootstrap window can close without mint or write",()=>{var f=new Fixture();var a=f.Scope();a.OpenBootstrapWindow();a.CloseUnusedBootstrapWindow();TestRunner.True(!a.BootstrapWindowOpen&&a.BootstrapGameId==null&&a.BootstrapFreezeCount==0,"Cleanup invented identity.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)!=null,"Closed unused window retained write permission.");});
 tests.Run("pure bootstrap plan never spends or freezes",()=>{var f=new Fixture();var a=f.Scope();for(int i=0;i<4;i++)TestRunner.True(a.MatchesNativeBootstrapPlan(f.Source,NewArea),"Exact plan refused.");TestRunner.True(a.BootstrapGameId==null&&!a.BootstrapWindowOpen,"Plan changed identity.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Plan spent write.");});
 foreach(var name in new[]{"load1","write2","foreign root","wrong hash","wrong source name","writable anchor","missing bootstrap","extra leaf","wrong area","foreign campaign","alternate area","bootstrap source"})tests.Run("bootstrap exact plan rejects "+name,()=>{var f=new Fixture();var entries=f.Entries();int? loads=0,writes=1;switch(name){case "load1":loads=1;break;case "write2":writes=2;break;case "wrong hash":f.Source.Sha256=new string('e',64);break;case "wrong source name":f.Source.InternalName="Foreign";break;case "writable anchor":entries[0].Writable=true;break;case "missing bootstrap":entries[1].Campaign=null;entries[1].AdmitsBeforeArea=false;break;case "extra leaf":entries=entries.Concat(new[]{new PersistenceSaveEntry{FileName="Auto_2.zks",InternalName="Auto",SaveType="Auto",Area=NewArea,Writable=true,Campaign="B"}}).ToArray();break;case "wrong area":entries[1].Area=Area;break;case "foreign campaign":f.Source.GameId=NewId;break;case "alternate area":f.Source.Area=NewArea;break;case "bootstrap source":f.Source.FileName="Auto_1.zks";break;}
 var a=f.Scope(entries,loads,writes);if(name=="foreign root"){TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root+"-foreign")!=null,"Foreign root accepted.");}else TestRunner.True(!a.MatchesNativeBootstrapPlan(f.Source,NewArea),"Foreign bootstrap plan accepted.");});
 tests.Run("historical uncapped authority remains uncapped",()=>{var f=new Fixture();var a=f.Scope(f.Entries(),null,null);for(int i=0;i<3;i++)TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Historical load unexpectedly capped.");});
 tests.Run("negative native load cap refused",()=>{var f=new Fixture();bool rejected=false;try{f.Scope(f.Entries(),-1,1);}catch(ArgumentException){rejected=true;}TestRunner.True(rejected,"Negative load cap admitted.");});
 return tests.Complete();}
 private static RuntimeRequest Request()=>new RuntimeRequest{SchemaVersion=2,RunId="bootstrap-test",Scenario=Chunk7NativeBootstrapSelection.Scenario,NativeBootstrap=new Chunk7NativeBootstrapSelection{Case=Chunk7NativeBootstrapSelection.MainCase,BaseGameOnly=true,ExpectedNativeLoadCount=0,ExpectedNativeWriteCount=1,NativeWriteLeaf="Auto_1.zks"},Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Id,TransactionToken=new string('3',64),EvidenceRoot=@"C:\KmcBootstrapVirtual\evidence",Fixture=new RuntimeFixtureIdentity{Baseline=Descriptor("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",new string('a',64)),Working=Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64)),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="bootstrap-suite",SnapshotSha256=new string('4',64)}};
 private static RuntimeSaveDescriptor Descriptor(string n,string f,string h)=>new RuntimeSaveDescriptor{InternalName=n,FileName=f,Sha256=h,Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Id,GameName="Anchor",Area=Area};
 private sealed class Fixture {
 internal readonly string Root=@"C:\KmcBootstrapVirtual\run\Saved Games";internal RuntimeSaveDescriptor Source=Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64));
 internal RuntimeSaveTarget Load=>new RuntimeSaveTarget{InternalName="KMC_AUTOMATION_WORKING",FileName="Manual_299_KMC_AUTOMATION_WORKING.zks",FullPath=Root+@"\Manual_299_KMC_AUTOMATION_WORKING.zks",SaveType="Manual",GameId=Id,GameName="Anchor",Area=Area};
 internal RuntimeSaveTarget Write=>new RuntimeSaveTarget{InternalName="Autosave",FileName="Auto_1.zks",FullPath=Root+@"\Auto_1.zks",SaveType="Auto",GameId=NewId,GameName="Native",Area=null};
 internal PersistenceSaveEntry[] Entries()=>new[]{new PersistenceSaveEntry{FileName=Load.FileName,InternalName=Load.InternalName,SaveType="Manual",Area=Area,InitialSha256=new string('b',64)},new PersistenceSaveEntry{FileName="Auto_1.zks",InternalName="Autosave",SaveType="Auto",Area=NewArea,Writable=true,Campaign="B",AdmitsBeforeArea=true}};
 internal PersistenceSaveAuthorization Scope(PersistenceSaveEntry[] entries=null,int? loads=0,int? writes=1)=>new PersistenceSaveAuthorization(@"C:\KmcBootstrapVirtual\run",Id,"Anchor",new string('a',64),entries??Entries(),null,null,writes,loads);
 }
}
// Only external filesystem calls are substituted. No save or archive is created,
// opened, parsed or changed by these actual-authority tests.
internal static class BootstrapVirtualDirectory { internal static IEnumerable<string> EnumerateFileSystemEntries(string path)=>new[]{path+@"\Manual_299_KMC_AUTOMATION_WORKING.zks"};internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal); }
internal static class BootstrapVirtualFile {internal static bool Exists(string path)=>path.EndsWith("Manual_299_KMC_AUTOMATION_WORKING.zks",StringComparison.Ordinal);internal static void Delete(string path){throw new InvalidOperationException("Unexpected filesystem mutation.");}}
internal static class BootstrapVirtualStorage {internal static void RequireDirectory(string path){if(!path.StartsWith(@"C:\KmcBootstrapVirtual\run",StringComparison.Ordinal))throw new InvalidOperationException("Foreign virtual root.");}internal static string Hash(string path){if(!BootstrapVirtualFile.Exists(path))throw new InvalidOperationException("Unowned virtual file.");return new string('b',64);}}
}
